(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],KEY='momcozy-framework-fw03';
const names={identity:'身份选择',stage:'所处阶段',basic:'基本信息',birth:'本次分娩',focus:'当前关注',recommend:'服务推荐',chat:'主对话',mine:'我的',baby:'宝宝',devices:'设备',breast:'亲喂',formula:'配方奶',bottle:'瓶喂母乳',diaper:'换尿布',pump:'吸奶'};
const order=['identity','stage','basic','birth','focus','recommend','chat'];
const types=['breast','formula','bottle','diaper','pump'];
const initial=()=>({inputs:{'ONB-date':'2026-10-07','ONB-count':'1'},sampleBirth:true,expanded:false,serial:0,records:[],messages:[],chatDraft:'',attachments:[],failedSend:null,tasks:{cry:{state:'ready',visible:false},poop:{state:'ready',visible:false,count:0}},editing:{},sound:false});
let epoch=0;let data=initial(),storage=true,route='',taskTimers={},recordClock=null,seconds=0,saving=false,sending=false,lastFocus=null;let sidebarReturn=false,sidebarScroll=0,sidebarSelected='',sidebarOpener=null,detailOpener=null;let chatScroll=0,chatReturnBottom=false,camera=null,todayExpanded=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed&&parsed.inputs&&Array.isArray(parsed.records)&&parsed.tasks){data={...initial(),...parsed};}}}catch{storage=false;}
if(!data.editing||typeof data.editing!=='object')data.editing={};
for(const t of Object.values(data.tasks)){if(t.state==='processing')t.state='error';if(t.state==='capture')t.state='ready';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localNow=()=>{const d=new Date();return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify(data));storage=true;}catch{storage=false;}$('#storage-note').textContent=storage?'演示数据保留于当前浏览器，重置仅清除此原型数据。':'浏览器存储不可用：当前仅在内存中保留，刷新会丢失。';};
function capture(){for(const el of $$('[name]'))data.inputs[el.name]=el.type==='checkbox'?el.checked:el.value;data.chatDraft=$('#chat-input').value;persist();}
function restore(){for(const el of $$('[name]')){const v=data.inputs[el.name];if(v!==undefined){if(el.type==='checkbox')el.checked=v;else el.value=v;}}$('#chat-input').value=data.chatDraft;render();}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,2600);}
function fail(s,el){$('#global-error').textContent=s;$('#global-error').hidden=false;if(el)el.focus();return false;}
function showDialog(title,body){$('#overlay').classList.toggle('sheet',title==='记录一次日常');lastFocus=document.activeElement;$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#overlay').showModal();}
function closeDialog(){$('#overlay').close();if(lastFocus?.isConnected)lastFocus.focus();}
function go(to){capture();if(location.hash==='#/'+to){showRoute();return;}location.hash='#/'+to;}
function showRoute(){if(route==='chat')chatScroll=$('#chat-stream').scrollTop;if(route==='chat'&&location.hash!=='#/chat'&&!$('#sidebar').open)sidebarScroll=window.scrollY;capture();route=location.hash.slice(2);if(!names[route]){route='chat';history.replaceState(null,'','#/chat');}document.body.classList.toggle('conversation-active',route==='chat'&&!!data.expanded);if(['mine','baby','devices'].includes(route))sidebarSelected=route;$$('[data-page-id]').forEach(e=>e.hidden=e.dataset.route!=='#/'+route);$('#global-error').hidden=true;$('#page-title').textContent=names[route];$('#page-description').textContent=types.includes(route)?'独立记录表单。共用时间、备注、保存反馈；类型专属字段保持不同含义。':route==='chat'?'年龄背景常显；今日概览、消息、记录与任务在同一连续对话流中。点击输入框同页展开，拍照和上传先确认再发送。':['mine','baby','devices'].includes(route)?'对象概览：信息摘要与两个下级入口；目标界面未提供的入口展示范围说明。返回恢复侧边栏，再关闭恢复对话。':'身份＋5步引导。只还原已提供的产后路径，返回保留输入。';if(types.includes(route)){const el=$(`[name="${route}-time"]`);if(!el.value)el.value=localNow();}render();$(`[data-route="#/${route}"] h1`)?.focus({preventScroll:true});if(route==='chat'&&sidebarReturn){sidebarReturn=false;window.scrollTo(0,sidebarScroll);openSidebar(false);}else window.scrollTo(0,0);document.body.classList.toggle('on-chat',route==='chat');if(route!=='chat')document.body.classList.remove('conversation-active');if(route==='chat'){requestAnimationFrame(()=>{if(chatReturnBottom){chatReturnBottom=false;scrollLatest()}else $('#chat-stream').scrollTop=chatScroll;});}}

const nextSeq=()=>++data.serial;
function ageLabel(born,today){if(!born)return '年龄待完善';const a=new Date(born+'T00:00:00Z'),b=new Date(today+'T00:00:00Z');if(!Number.isFinite(+a)||a.toISOString().slice(0,10)!==born||a>b)return '出生日期待核实';const days=Math.round((b-a)/86400000);if(!days)return '今天出生';let months=(b.getUTCFullYear()-a.getUTCFullYear())*12+b.getUTCMonth()-a.getUTCMonth();const anniversary=n=>{const d=new Date(Date.UTC(a.getUTCFullYear(),a.getUTCMonth()+n,1));d.setUTCDate(Math.min(a.getUTCDate(),new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)).getUTCDate()));return d;};if(anniversary(months)>b)months--;if(months<1)return '出生 '+days+' 天';const rest=Math.round((b-anniversary(months))/86400000);return months+' 个月'+(rest?' '+rest+' 天':'');}
function todayRecords(){const today=localNow().slice(0,10);return data.records.filter(r=>(r.values[r.type+'-time']||'').slice(0,10)===today).sort((a,b)=>(b.values[b.type+'-time']||'').localeCompare(a.values[a.type+'-time']||''));}
function draftType(){return types.find(k=>Object.entries(data.inputs).some(([name,value])=>name.startsWith(k+'-')&&!name.endsWith('-time')&&value));}
function renderToday(){const rs=todayRecords();$('#today-date').textContent=localNow().slice(5,10).replace('-',' / ');$('#today-summary').textContent=rs.length?'今天已保存 '+rs.length+' 条记录，最近一条是'+names[rs[0].type]+'。':'今天暂无已保存记录，可以先记一笔，也可以直接聊聊。';$('#today-counts').hidden=!rs.length;$('#today-counts').innerHTML=[['喂养',rs.filter(r=>['breast','formula','bottle'].includes(r.type)).length],['换尿布',rs.filter(r=>r.type==='diaper').length],['吸奶',rs.filter(r=>r.type==='pump').length]].map(([label,count])=>'<span>'+label+'<strong>'+count+' 条</strong></span>').join('');const k=draftType();$('#today-draft').hidden=!k;$('[data-control-id="TODAY-resume"]').textContent=k?'继续填写'+names[k]:'继续未完成的记录';$('#today-details').hidden=!todayExpanded;$('[data-control-id="TODAY-details"]').textContent=todayExpanded?'收起今日记录':'展开今日记录';$('#today-details').innerHTML=rs.length?rs.map(r=>'<div class="today-record"><strong>'+esc(names[r.type])+'</strong><br>'+esc(summary(r))+'</div>').join(''):'<p class="fine">今天暂无已保存记录。</p>';}
function scrollLatest(){const el=$('#chat-stream');el.scrollTop=el.scrollHeight;}
function resizeComposer(){const el=$('#chat-input');el.style.height='auto';el.style.height=Math.min(112,Math.max(document.body.classList.contains('conversation-active')?72:52,el.scrollHeight+2))+'px';el.style.overflowY=el.scrollHeight>112?'auto':'hidden';}
function expandConversation(focus=false){data.expanded=true;document.body.classList.add('conversation-active');persist();resizeComposer();if(focus)$('#chat-input').focus({preventScroll:true});requestAnimationFrame(scrollLatest);}
function renderTimeline(){const stream=$('#chat-stream'),before=stream.scrollTop;stream.querySelectorAll('.timeline-dynamic').forEach(el=>el.remove());const nodes=[];
 for(const m of data.messages){if(!m.seq)m.seq=nextSeq();const el=document.createElement('div');el.className='message timeline-dynamic '+(m.role==='user'?'user':'');el.innerHTML='<small>'+ (m.role==='user'?'你':'Momcozy AI · 演示')+'</small>'+esc(m.text)+(m.attachments||[]).map(a=>'<div class="sent-attachment">'+esc(a.name)+' · '+esc(a.source)+' · 模拟附件</div>').join('')+(m.action?'<button data-action="new:'+esc(m.action)+'">记录'+esc(names[m.action])+'</button>':'');nodes.push({seq:m.seq,el});}
 for(const r of data.records){if(!r.seq)r.seq=nextSeq();const el=document.createElement('article');el.className='saved timeline-dynamic';el.innerHTML='<div class="eyebrow">'+(storage?'已保存至本浏览器':'仅保留于当前页面')+'</div><h2>'+esc(names[r.type])+' · '+(r.type==='pump'?'妈妈':'宝宝')+'</h2><p>'+esc(summary(r))+'</p><button data-action="edit:'+esc(r.id)+'">查看 / 修改记录</button>';nodes.push({seq:r.seq,el});}
 for(const kind of ['cry','poop']){const t=data.tasks[kind],el=$('#'+kind+'-card');if(t.visible){if(!t.seq)t.seq=nextSeq();nodes.push({seq:t.seq,el});}}
 if(camera)nodes.push({seq:camera.seq,el:$('#camera-panel')});
 nodes.sort((a,b)=>a.seq-b.seq).forEach(n=>stream.appendChild(n.el));stream.appendChild($('#generating').parentElement);stream.appendChild($('#chat-error').parentElement);stream.scrollTop=before;
}
function render(){const born=data.inputs['ONB-date'],count=data.inputs['ONB-count'];$('#stage-context').textContent=ageLabel(born,localNow().slice(0,10));$('#age-date').textContent=born?born.replaceAll('-','.')+' 出生'+(data.sampleBirth?' · 示例资料':''):'补充出生日期后显示';$('#baby-context').textContent=(count&&count!=='1'?count+'个宝宝（未分档） · ':'宝宝 · ')+$('#stage-context').textContent;$$('.record-baby').forEach(e=>e.textContent=count&&count!=='1'?'本次分娩背景（未分宝宝）':'本次背景');$('[data-control-id="C03"]').textContent=data.sound?'声音开启（模拟）':'声音关闭';
 $('#attachment').hidden=!data.attachments.length;$('#attachment-items').innerHTML=data.attachments.map(a=>'<div class="attachment-item"><span>'+esc(a.name)+'<br><small>'+esc(a.source)+' · 模拟素材</small></span><button aria-label="移除'+esc(a.name)+'" data-action="remove-attachment:'+esc(a.id)+'">移除</button></div>').join('');
 for(const kind of ['cry','poop']){const task=data.tasks[kind],card=$('#'+kind+'-card');card.hidden=!task.visible;card.querySelectorAll('[data-task-state]').forEach(el=>el.hidden=el.dataset.taskState!==task.state);card.querySelector('.task-footer').hidden=['cancelled','result','unknown'].includes(task.state);$('#'+kind+'-preview').textContent=kind==='cry'?'模拟录音 · '+(task.seconds||0)+' 秒（未采集真实音频）':'已选择 '+(task.count||0)+' / 3 张模拟图片';}
 $('#camera-panel').hidden=!camera;$$('[data-camera-state]').forEach(el=>el.hidden=el.dataset.cameraState!==camera?.state);$('#chat-error').hidden=!data.failedSend;$('#failed-preview').textContent=data.failedSend?data.failedSend.text+' '+data.failedSend.attachments.map(a=>a.name).join('、'):'';renderToday();renderTimeline();resizeComposer();
}
function addAttachment(kind,source){data.attachments.push({id:'attachment-'+nextSeq(),name:kind==='file'?'示例文档.pdf':'示例照片 '+(data.attachments.filter(a=>a.kind!=='file').length+1),kind,source});persist();render();}
function mediaAction(action,arg){if(action==='camera-open'){expandConversation();$('#upload-panel').hidden=true;camera={seq:camera?.seq||nextSeq(),state:$('#scenario-permission').value==='deny'?'error':'ready'};render();scrollLatest();$('#camera-panel h2').focus({preventScroll:true});}
 else if(action==='camera-shutter'){if(camera)camera.state='preview';render();scrollLatest();}
 else if(action==='camera-retake'){if(camera)camera.state='ready';render();}
 else if(action==='camera-use'){if(camera?.state!=='preview')return;camera=null;addAttachment('image','拍照');expandConversation(true);}
 else if(action==='camera-cancel'){camera=null;render();$('[data-control-id="C13"]').focus({preventScroll:true});}
 else if(action==='upload-open'){expandConversation();$('#upload-panel').hidden=!$('#upload-panel').hidden;$('#upload-error').hidden=true;$('[data-control-id="C15"]').setAttribute('aria-expanded',String(!$('#upload-panel').hidden));}
 else if(action==='upload-close'){$('#upload-panel').hidden=true;$('#upload-error').hidden=true;$('[data-control-id="C15"]').setAttribute('aria-expanded','false');$('[data-control-id="C15"]').focus();}
 else if(action==='upload'){if($('#scenario-upload').value==='fail'){$('#upload-error').hidden=false;return;}$('#upload-error').hidden=true;$('#upload-panel').hidden=true;$('[data-control-id="C15"]').setAttribute('aria-expanded','false');addAttachment(arg==='file'?'file':'image',arg==='file'?'文件选择':'相册');expandConversation(true);}
 else if(action==='remove-attachment'){data.attachments=data.attachments.filter(a=>a.id!==arg);persist();render();}
 else if(action==='clear-attachments'){data.attachments=[];persist();render();}
}
function summary(r){const v=r.values,k=r.type;let s=(v[k+'-time']||'').replace('T',' ')+' · '+(r.timezone||'设备本地时间')+'\n';if(k==='breast')s+=v[k+'-side']+' · '+v[k+'-duration']+' 分钟';else if(k==='diaper')s+=v[k+'-diaper']+' · 红屁屁：'+v[k+'-rash'];else s+=v[k+'-amount']+' ml'+(v[k+'-end']?' · 结束 '+v[k+'-end'].replace('T',' '):'');if(v[k+'-note'])s+='\n备注：'+v[k+'-note'];return s;}
function next(){capture();let required={identity:['ONB-role'],stage:['ONB-stage'],basic:['ONB-age','ONB-parity'],birth:['ONB-date','ONB-week','ONB-count']}[route]||[];for(const key of required){const el=$(`[name="${key}"]`);if(!el.value||!el.checkValidity())return fail('请补充或检查：'+el.closest('label').childNodes[0].textContent,el);}if(route==='stage'&&data.inputs['ONB-stage']!=='产后'){$('#stage-note').hidden=false;return;}if(route==='birth'&&data.inputs['ONB-date']>localNow().slice(0,10))return fail('分娩日期不能晚于今天。',$('[name="ONB-date"]'));go(order[order.indexOf(route)+1]||'chat');}

function positionSidebar(){const r=$('.device').getBoundingClientRect();const el=$('#sidebar');const top=Math.max(12,r.top);el.style.left=Math.max(0,r.left)+'px';el.style.top=top+'px';el.style.width=Math.min(350,r.width*.85)+'px';el.style.height=Math.min(Math.max(300,r.height),window.innerHeight-top-12)+'px';}
function openSidebar(remember=true){capture();if(remember){sidebarScroll=window.scrollY;sidebarOpener=document.activeElement;}const el=$('#sidebar');el.querySelectorAll('[data-action^="sidebar-go:"]').forEach(b=>{if(b.dataset.action==='sidebar-go:'+sidebarSelected)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});positionSidebar();if(!el.open)el.showModal();$('[data-control-id="C01-close"]').setAttribute('aria-label','关闭侧边栏');$('[data-control-id="C01-close"]').focus();}
function closeSidebar(){if($('#sidebar').open)$('#sidebar').close();window.scrollTo(0,sidebarScroll);if(sidebarOpener?.isConnected&&sidebarOpener.getClientRects().length)sidebarOpener.focus({preventScroll:true});else $('[data-control-id="C01"]').focus({preventScroll:true});}
function backToSidebar(){sidebarReturn=true;go('chat');}
function closeDetail(){const d=$('.scope-dialog[open]');if(d)d.close();if(detailOpener?.isConnected)detailOpener.focus({preventScroll:true});}

function recordMenu(){showDialog('记录一次日常',`<p class="muted">选择类型，进入对应表单。</p><div class="dialog-list">${types.map((x,i)=>`<button data-action="new:${x}">${names[x]}<small>${['侧别与时长','奶量与时间','奶量与时间','尿布状态与观察','妈妈的吸奶量'][i]}</small></button>`).join('')}</div>`);}
function save(k){if(saving)return;capture();const keys=[k+'-time',...(k==='breast'?[k+'-side',k+'-duration']:k==='diaper'?[k+'-diaper',k+'-rash']:[k+'-amount'])];const err=$('#'+k+'-error');err.hidden=true;for(const key of keys){const el=$(`[name="${key}"]`);if(!el.value||!el.checkValidity()){err.textContent='请检查必填字段，数值需大于 0。';err.hidden=false;el.focus();return;}}const start=data.inputs[k+'-time'],end=data.inputs[k+'-end'];if(start>localNow()||end&&(end<start||end>localNow())){err.textContent='请检查时间：不能晚于当前时间，结束不能早于开始。';err.hidden=false;return;}const values=Object.fromEntries(Object.entries(data.inputs).filter(([key])=>key.startsWith(k+'-'))), editId=data.editing[k], operationEpoch=epoch;saving=true;$$(`[data-page-id="PAGE-${k}"] [name]`).forEach(el=>el.disabled=true);$('#'+k+'-saving').hidden=false;$(`[data-control-id="${k}-save"]`).disabled=true;setTimeout(()=>{if(epoch!==operationEpoch)return;saving=false;$$(`[data-page-id="PAGE-${k}"] [name]`).forEach(el=>el.disabled=false);$('#'+k+'-saving').hidden=true;$(`[data-control-id="${k}-save"]`).disabled=false;if($('#scenario-save').value==='fail'){err.textContent='保存失败，填写内容已保留。请切换正常场景后重试。';err.hidden=false;return;}const id=editId||'rec-'+Date.now();const r={id,type:k,seq:data.records.find(r=>r.id===id)?.seq||nextSeq(),values,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,createdAt:new Date().toISOString()};const idx=data.records.findIndex(x=>x.id===id);if(idx<0)data.records.push(r);else data.records[idx]=r;delete data.editing[k];for(const el of $$(`[data-page-id="PAGE-${k}"] [name]`)){el.value='';delete data.inputs[el.name];}capture();chatReturnBottom=true;go('chat');toast(storage?'记录已保存至本浏览器':'仅保留于当前页面，刷新会丢失');},450);}
function edit(id,force=false){const r=data.records.find(x=>x.id===id);if(!r)return;capture();const dirty=$$(`[data-page-id="PAGE-${r.type}"] [name]`).some(el=>!el.name.endsWith('-time')&&el.value);if(!force&&dirty){if(data.editing[r.type]===id){go(r.type);return;}showDialog('已有未保存填写','<p>同类型有未保存内容，请选择继续或放弃后打开另一条记录。</p><div class="dialog-list"><button data-action="resume-type:'+r.type+'">继续已有填写</button><button data-action="replace-edit:'+id+'">放弃已有填写并打开记录</button></div>');return;}data.editing[r.type]=id;for(const el of $$(`[data-page-id="PAGE-${r.type}"] [name]`)){el.value=r.values[el.name]||'';}capture();go(r.type);}
function taskAction(kind,action){const t=data.tasks[kind];
 if(action==='open'){if(!t.visible)t.seq=nextSeq();t.visible=true;if(['cancelled','result','unknown'].includes(t.state)){data.messages.push({role:'assistant',seq:t.seq,text:(kind==='cry'?'听哭闹':'看便便')+' · 上次任务'+(t.state==='cancelled'?'已取消':t.state==='unknown'?'无法判断':'已完成（结构示例）')+'。'});t.state='ready';t.count=0;t.seconds=0;t.seq=nextSeq();}go('chat');render();requestAnimationFrame(()=>{const stream=$('#chat-stream'),card=$('#'+kind+'-card');stream.scrollTop+=card.getBoundingClientRect().top-stream.getBoundingClientRect().top-12;card.querySelector('h2').focus({preventScroll:true});});return;}
 if(action==='cancel'){clearTimeout(taskTimers[kind]);if(kind==='cry')clearInterval(recordClock);t.state='cancelled';t.count=0;t.seconds=0;}
 if(action==='restart'){t.state='ready';t.count=0;t.seconds=0;}
 if(action==='start'){if(data.tasks.cry.state==='capture')return;if($('#scenario-permission').value==='deny'){t.state='permission';}else{t.state='capture';seconds=0;$('#recording-time').textContent='00:00';clearInterval(recordClock);recordClock=setInterval(()=>{seconds++;$('#recording-time').textContent='00:'+String(seconds).padStart(2,'0');},1000);}}
 if(action==='stop'){clearInterval(recordClock);t.seconds=Math.max(1,seconds);t.state='preview';}
 if(action==='add'){if($('#scenario-permission').value==='deny'){t.state='permission';}else if((t.count||0)>=3){toast('最多添加 3 张图片');}else{t.count=(t.count||0)+1;t.state='preview';}}
 if(action==='remove'){t.count=Math.max(0,(t.count||0)-1);t.state=t.count?'preview':'ready';}
 if(action==='submit'){if(t.state==='processing')return;if(kind==='poop'&&!t.count||kind==='cry'&&!t.seconds){t.state='ready';}else{t.state='processing';const outcome=$('#scenario-analysis').value;clearTimeout(taskTimers[kind]);taskTimers[kind]=setTimeout(()=>{t.state=outcome;persist();render();},1000);}}
 if(action==='ask'){$('#chat-input').value='关于刚才的'+(kind==='cry'?'哭声':'便便')+'结果，我想补充：';$('#chat-input').focus();toast('已带入任务名称，请补充情况');}
 persist();render();
}

function send(retry=false){if(sending)return;if(data.failedSend&&!retry){toast('请先重试或放弃上一条失败消息；当前输入仍会保留。');return;}const input=$('#chat-input');const submission=retry?data.failedSend:{text:input.value.trim(),attachments:data.attachments.map(a=>({...a}))};if(!submission||!submission.text&&!submission.attachments.length){toast('请先输入内容或添加附件');return;}capture();const operationEpoch=epoch;sending=true;$('#generating').hidden=false;$('[data-control-id="CHAT-send"]').disabled=true;expandConversation();scrollLatest();setTimeout(()=>{if(epoch!==operationEpoch)return;sending=false;$('#generating').hidden=true;$('[data-control-id="CHAT-send"]').disabled=false;if($('#scenario-save').value==='fail'){data.failedSend=submission;persist();render();scrollLatest();return;}data.messages.push({role:'user',seq:nextSeq(),text:submission.text||'请看看这份附件',attachments:submission.attachments},{role:'assistant',seq:nextSeq(),text:'已收到。'+(submission.attachments.length?'附件已随这条消息保留；本演示不进行真实上传或内容分析。':'这里演示连续对话，消息会接着出现在当前页面。'),action:submission.text.includes('配方奶')?'formula':null});if(input.value.trim()===submission.text){input.value='';data.chatDraft='';}else data.chatDraft=input.value;data.attachments=data.attachments.filter(a=>!submission.attachments.some(s=>s.id===a.id));data.failedSend=null;persist();render();scrollLatest();},600);}
const scopeHTML=`<p><strong>本版：独立产品容器，范围限定为已录入功能。</strong></p><h3>原始来源</h3><p>「重构需求拆解与原型交互」聊天 2026-10-19 的 21 张截图与拆解，已保存在 sources。保留 C01–C15、C09.1–C09.5，补充 C01.1–C01.3 及六个下级入口编号。</p><h3>必要完善（候选规则）</h3><p>返回保留草稿；五类记录本地保存并回到会话；记录可修改；亲喂时长采用手动补记；素材先确认再分析；失败重试与取消。</p><h3>待定业务</h3><p>奶量含义、亲喂计时、年龄和孕周范围、正式默认值、时间与单位规则、语音与声音入口具体行为。数值和校验仅用于演示。</p><h3>范围外 / 未提供</h3><p>六个下级入口的未提供目标界面、备孕与孕期分支、多宝宝分档、账号、家庭共享、设备绑定、商城、通知、后台同步、真实 AI / 麦克风 / 相机。</p><p>情绪板仅作方向参考。本版框架与设计规范尚未冻结。</p>`;
document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button)return;if(sending&&['camera-open','camera-shutter','camera-retake','camera-use','camera-cancel','upload-open','upload','remove-attachment','clear-attachments','voice','voice-text','retry-send','discard-failed'].includes(button.dataset.action.split(':')[0])){toast('正在发送，完成后可添加下一条素材');return;}if(saving&&button.dataset.action!=='reset-confirm'){toast('正在保存，请稍候');return;}const [action,arg,more]=button.dataset.action.split(':');$('#global-error').hidden=true;
if(action==='go'||action==='review')go(arg);else if(action==='next')next();else if(action==='menu')openSidebar();else if(action==='sidebar-close')closeSidebar();else if(action==='sidebar-go'){sidebarSelected=arg;$('#sidebar').close();go(arg);}else if(action==='overview-back')backToSidebar();else if(action==='overview-detail'){detailOpener=button;$('#detail-'+arg).showModal();}else if(action==='detail-close')closeDetail();else if(action==='review-sidebar'){if(route==='chat')openSidebar();else{sidebarReturn=true;go('chat');}}else if(action==='sound'){data.sound=!data.sound;persist();render();toast('声音状态为模拟，本版不自动播放');}else if(action==='record-menu')recordMenu();else if(action==='new'){closeDialog();go(arg);}else if(action==='close-dialog')closeDialog();else if(action==='save')save(arg);else if(action==='exit'){capture();if(saving){toast('正在保存，请稍候');return;}const hasInput=$$(`[data-page-id="PAGE-${arg}"] [name]`).some(el=>!el.name.endsWith('-time')&&el.value);if(hasInput)showDialog('保留这次填写？','<p>保留后可从同一记录类型继续。</p><div class="dialog-list"><button data-action="keep-draft">保留草稿并返回</button><button data-action="discard:'+arg+'">放弃填写并返回</button><button data-action="close-dialog">继续填写</button></div>');else go('chat');}else if(action==='keep-draft'){closeDialog();go('chat');}else if(action==='discard'){for(const el of $$(`[data-page-id="PAGE-${arg}"] [name]`))el.value='';delete data.editing[arg];capture();closeDialog();go('chat');}else if(action==='edit')edit(arg);else if(action==='resume-type'){closeDialog();go(arg);}else if(action==='replace-edit'){closeDialog();edit(arg,true);}else if(action==='amount'){const el=$(`[name="${arg}-amount"]`);el.value=Math.max(0,Number(el.value||0)+Number(more));capture();}else if(action==='cry'||action==='poop')taskAction(action,arg);else if(action==='send')send();else if(action==='retry-send')send(true);else if(action==='discard-failed'){data.failedSend=null;persist();render();}else if(action==='today-details'){todayExpanded=!todayExpanded;renderToday();}else if(action==='today-resume'){const k=draftType();if(k)go(k);}else if(action==='collapse-input'){data.expanded=false;persist();document.body.classList.remove('conversation-active');$('#chat-input').blur();resizeComposer();}else if(action.startsWith('camera-')||action.startsWith('upload')||['clear-attachments','remove-attachment'].includes(action))mediaAction(action,arg);else if(action==='voice')showDialog('语音输入 · 模拟','<p>原入口具体语音形态尚未定义。本版仅演示“转成文字 → 用户确认发送”。</p><button data-action="voice-text">使用示例转写</button>');else if(action==='voice-text'){$('#chat-input').value='我想了解如何记录这次喂养。';capture();closeDialog();}else if(action==='scope')showDialog('范围与来源',scopeHTML);else if(action==='reset')showDialog('重置演示','<p>只清除此框架的虚构输入、会话、任务与记录。</p><button data-action="reset-confirm" class="primary">确认重置</button>');else if(action==='reset-confirm'){epoch++;saving=false;sending=false;$('#generating').hidden=true;$('[data-control-id="CHAT-send"]').disabled=false;clearInterval(recordClock);Object.values(taskTimers).forEach(clearTimeout);data=initial();camera=null;todayExpanded=false;chatScroll=0;$('#upload-panel').hidden=true;$('#upload-error').hidden=true;document.body.classList.remove('conversation-active');$$('[name]').forEach(el=>{el.disabled=false;if(el.type==='checkbox')el.checked=false;else el.value='';});$('#chat-input').value='';data.inputs={};data.sampleBirth=false;persist();closeDialog();go('chat');}
});
document.addEventListener('input',e=>{if(e.target.matches('[name],#chat-input')){capture();renderToday();if(e.target.id==='chat-input')resizeComposer();if(e.target.name==='ONB-date'){data.sampleBirth=false;persist();}}});document.addEventListener('change',e=>{if(e.target.name==='ONB-stage')$('#stage-note').hidden=e.target.value==='产后';});
$('#chat-input').addEventListener('focus',()=>expandConversation());
$('#chat-input').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();send();}});
$('#overlay').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
$('#sidebar').addEventListener('cancel',e=>{e.preventDefault();closeSidebar()});$('#sidebar').addEventListener('click',e=>{if(e.target!==$('#sidebar'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSidebar()});$$('.scope-dialog').forEach(d=>d.addEventListener('cancel',e=>{e.preventDefault();closeDetail()}));window.addEventListener('resize',()=>{if($('#sidebar').open)positionSidebar()});window.addEventListener('hashchange',()=>{if($('#sidebar').open)$('#sidebar').close();$$('.scope-dialog[open]').forEach(d=>d.close());showRoute()});window.addEventListener('pagehide',capture);
data.attachments=Array.isArray(data.attachments)?data.attachments:[];data.serial=Number(data.serial)||0;restore();persist();showRoute();
})();
